def forward(groups):
    date_part = groups[0]
    space_part = groups[1]
    time_part = groups[2]
    timestamp = datetime.strptime(date_part + time_part, '%y%m%d%H%M%S')
    spaces = len(space_part)
    return {'stored': [int(timestamp.timestamp() * 1000000), spaces], 'layout': []}

def inverse(record):
    micros = int(record['stored'][0])
    spaces = int(record['stored'][1])
    timestamp = datetime.fromtimestamp(micros / 1000000)
    return timestamp.strftime('%y%m%d' + (' ' * spaces) + '%H%M%S')
